insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 1, 'One wildcat with pos 0.3, a success-case NPV of 300 and a fail cost of 50. Before EC5-0 the engine put its P90 at -150.5560. What is wrong with that figure?', '["Nothing is wrong with it: a low case set beneath the worst outcome is a conservative margin, and the simulation has simply removed that margin.", "It is the high case with its sign reversed, because the old engine ranked outcomes under the opposite percentile convention to the one used now.", "It sits beneath -50.0000, the worst outcome the well can produce, so it describes a loss this project can never book.", "It is right for the success case alone, since the old engine drew the failure lump in a separate pass and never added it back into the sum."]'::jsonb, 2, 'The old P90 was emv minus 1.2816 x stdDev on a bell the well does not have: it fails with chance 0.700000 and then loses exactly 50.0000, which is the engine''s P90 now, -50.0000.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 2, 'A reviewer proposes keeping the normal approximation and adding a fixed safety margin to its P(loss). The identical wildcat cases read 0.276275 against an exact 0.343000 for three wells and 0.200464 against 0.117649 for six. Why does the margin fail?', '["The error changes sign as wells are added, understated with three and overstated with six, so no single margin leans the right way.", "A fixed margin would have to be reset for every seed, since the approximation is redrawn on each run.", "The margin would move P(loss) and leave P90 untouched, because the approximation read the two figures off two different fitted curves.", "The approximation is already conservative on every published case, so a margin double counts risk."]'::jsonb, 0, 'An error that flips sign cannot be corrected by leaning one way: with eight wells it understates again, 0.166046 against an exact 0.255298.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 3, 'On which published cases does the normal approximation give the exact P(loss)?', '["The large identical wildcat cases, where eight wells are enough outcomes for the lumps to converge on a normal curve and the approximation settles.", "The comonotone cases, where every project fails together, so the portfolio behaves as one project and a single fitted curve describes it exactly.", "The three mixed wildcats, where the different fail costs spread the lumps apart and smooth the sum into the shape of a normal distribution.", "The pos1-normal cases, projects that always succeed with a normal spread, where the portfolio value really is a bell."]'::jsonb, 3, 'normalPairIndependent reads 0.001571 both ways and normalThreeCorrelated 0.231959, while comonotoneIdentical3 reads 0.365832 against 0.700000 and identical8 0.166046 against 0.255298.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 4, 'In a simulated iteration where OK-3 fails, what does the engine book for it?', '["Its npv_p90 of 210.0000, the low percentile of its entered range, which is the value a well lands on when its success driver misses.", "Minus 85.0000 exactly, in every failing iteration, since the success spread scales a success and a failure is a single number.", "Minus 85.0000 plus its success spread of 191.1747 times z2, because both of its drivers are drawn in every iteration and both are applied.", "A normal draw around minus 85.0000 scaled by its mixture sd of 238.6507, which folds in the failure lump."]'::jsonb, 1, 'OK-3 fails with chance 0.750000 and books 85.0000 of loss each time, which is why its risked EMV is 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 and why small portfolios have spikes.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 5, 'mixtureWithSpread pairs a risked project with a sure one. Before EC5-0 the engine put its P90 at -12.4175; the simulation reads 1.7148. What would a reader of the old figure have got wrong?', '["Nothing of substance, since both figures sit close to zero and the gap between them is inside one standard error of the simulated count.", "The sign of the high case, because under the exceedance convention the old P90 was the figure a committee would quote as the upside.", "That the low case loses money, when nine simulated outcomes in ten are gains.", "The worst case, because a P90 of -12.4175 is the floor of the portfolio and the simulation shows the floor is really a small gain."]'::jsonb, 2, 'Under the exceedance convention P90 is the 10th percentile of simulated portfolio NPV, and at 1.7148 it is a gain; the bell fitted to emv and stdDev put it at a loss of 12.4175.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 6, 'OK-3''s npv_p10 of 700.0000 sits further above its npv_p50 of 420.0000 than its npv_p90 of 210.0000 sits below it. What does the simulation keep of that shape?', '["The skew as well, since a success above the median is scaled by the upper half of the range and one below it by the narrower lower half.", "Nothing of the percentiles at all, because a project with pos 0.250000 is drawn from its mixture sd of 238.6507 on every iteration.", "The upper half of the range only, since a success is never drawn below its npv_p50 of 420.0000 and a failure books the downside instead.", "Only the width, as a success spread of 191.1747 drawn symmetrically around 420.0000, so the skew is discarded."]'::jsonb, 3, 'The success spread is (700.0000 - 210.0000) / 2.5631 = 191.1747 and z2 is a symmetric normal, so a wide spread can occasionally put a success below zero.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 7, 'Two runs at the default seed differ only in one project''s pos. Why is the gap between their results readable as the effect of that change?', '["The draw order never depends on the inputs, so every project receives the same normals in both runs and only the change moves the result.", "The engine reseeds each project from its id, so a project whose pos is untouched redraws exactly what it drew before, while the edited one draws afresh.", "A project with a different pos skips its unused e1 draw, and skipping one normal shifts the stream by a known amount that the engine corrects for.", "The seed advances by one for each run, so two runs always differ by a single step of sampling noise and the rest of the gap is the edit."]'::jsonb, 0, 'Each iteration draws F1, F2, then e1 and e2 per project in array order from mulberry32(20260829), and every normal is drawn whether or not it is used.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 8, 'An analyst lists the 450.0000 set''s projects in a different order and P(loss) moves off 0.123600, with the seed and iterations unchanged. Why?', '["The optimizer breaks ties by entry order, so the reordered list funds a different set at 450.0000 and the risk summary is simulated for that set.", "F1 and F2 are drawn after the last project, so moving a project changes which shared draws it hears.", "The e1 and e2 normals are dealt to projects in array order, so a new order hands each project different draws and the figure moves by sampling noise.", "The grid charges cells in entry order, so the reordered set weighs differently and its capex is simulated at a new total."]'::jsonb, 2, 'The set is still OK-1 + OK-3 + OK-4 and the seed still 20260829; anyone reproducing a figure needs the seed, the iteration count and the project order.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 9, 'A team tries seeds until P(loss) for OKONO''s 450.0000 set prints 0.119100, which seed 3 gives, and reports that figure. The default seed reads 0.123600 with a standard error of 0.003291. What is the problem with the report?', '["There is none, because every seed is exactly reproducible and any reproducible figure is as true as the default one.", "0.119100 is below the exact P(loss) of the set, which the engine prints as 0.123600 whenever it runs at its default seed.", "0.119100 is a 1000 iteration figure, since the engine drops to 1000 iterations whenever a seed other than the default is given.", "It picks the draw that flatters the set and reduces no risk; an honest report names the seed and iterations beside the figure."]'::jsonb, 3, 'At 10000 iterations seeds 1 to 3 give 0.119100 to 0.128500; each is reproducible and none is the answer, and a difference smaller than the standard error is noise.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 10, 'A user runs the risk summary with a seed that is not a whole number and an iteration count of 0. What runs?', '["Seed 20260829 and 10000 iterations, the defaults, taken silently in place of what was typed.", "Nothing: the input is refused with an error, as a negative capex is.", "The seed rounded to a whole number and one iteration, the smallest sample it takes.", "The closed-form emv and stdDev only, with P(loss), P90 and P10 returned as null because no simulation could be drawn."]'::jsonb, 0, 'A seed that is not a whole number falls back to 20260829 and an iteration count below 1 falls back to 10000, so the figures are the default run whatever the label says.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 11, 'The engine counts P(loss) 0.696100 for the single wildcat against an exact 0.700000, with a standard error of 0.004583. Is the engine wrong?', '["Yes, because a reproducible seeded run ought to land on the exact P(loss).", "Yes, because the strict test drops iterations that net exactly zero, which biases the count below the exact loss chance.", "No, it sits 0.8510 standard errors from the exact figure, where a count from 10000 iterations should land.", "No, because the engine rounds P(loss) to the nearest standard error before printing it."]'::jsonb, 2, 'probLoss is a proportion with standard error sqrt(p(1 - p) / n); the largest z on the published cases is 1.4289, and the old 0.365832 sat dozens of standard errors away.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 12, 'identical6 loses with chance 0.117649 and OKONO''s 450.0000 set with 0.123600. What does the pair show?', '["identical6 is the safer portfolio, since its loss chance is lower and six wells spread the risk.", "P(loss) counts how often and never how much: every identical6 loss is -300.0000, while the 450.0000 set''s low case is -18.3574.", "The two carry the same downside, because equal loss chances over 10000 iterations imply equal average losses when those losses happen.", "The 450.0000 figure is the weaker one, because a set whose successes carry a spread cannot be counted and is approximated instead."]'::jsonb, 1, 'identical6 loses only when all six wells fail at 50.0000 each; two portfolios with nearly the same P(loss) can hold very different downsides, so the figure is read beside the low case.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 13, 'The 600.0000 set reads P(loss) 0.001800 and the 450.0000 set 0.123600. A committee concludes the optimizer picked a safer set at 600.0000. What is wrong?', '["The optimizer maximises risked EMV under the limit and never reads P(loss), so the lower figure is a by-product of a different budget''s set.", "Nothing, since the engine deducts each candidate set''s simulated loss chance from its EMV before solving, so safety is part of every choice it makes.", "The two figures come from different seeds, since each limit is simulated on a seed of its own and the comparison mixes two samples.", "The 600.0000 set looks safer only because it holds more projects, and the optimizer is written to prefer the larger set whenever two sets tie."]'::jsonb, 0, 'Both sets were simulated at seed 20260829 and 10000 iterations; a committee that wants less loss chance has to state that as its own constraint and test sets by hand.'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 14, 'The engine prints P(loss) 0.001800 for OKONO''s 600.0000 set, to six decimals. What should a reader add before relying on it?', '["Nothing, because six decimals at 10000 iterations resolve a loss probability to one part in a million and leave no room for error.", "The exact P(loss) the risk summary prints beside every OKONO set, which is the figure the simulated count is there to confirm.", "The normal approximation''s 0.002555, which is the more precise figure for a small probability because it needs no count.", "Its standard error, worked by hand as sqrt(p(1 - p) / n), because the engine prints none and a small count is the least precise relative to its size."]'::jsonb, 3, 'Few iterations fall below zero at 0.001800, so the count rests on a handful of draws; the engine reports no exact figure for OKONO and no standard error beside any P(loss).'),
  ('portfolio', 'advanced', 'module', 'm01-portfolio-risk-by-simulation', 15, 'identical8 is eight wildcats, each pos 0.3, 300 on success and a fail cost of 50. The engine''s P90 is -50.0000. What outcome is that?', '["The worst case, since P90 under the exceedance convention is the floor beneath which no simulated outcome of the portfolio falls.", "The 10th percentile: one success at 300 and seven failures at 50 each, a low case the portfolio reaches but not its worst, which is all eight failing.", "A single well''s failure, because the engine reports the P90 of the largest funded project in place of a percentile of the whole portfolio.", "The high case of the portfolio, the value exceeded by only one outcome in ten, which the exceedance convention labels P90."]'::jsonb, 1, 'P90 is the low case, the 10th percentile of simulated portfolio NPV. The engine reports no minimum, so the worst outcome of a risked set is written by hand, here eight failures at 50.0000 each.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 1, 'A planner types a negative correlation to represent a project that does well when the others do badly. What does the engine run?', '["Nothing: the input is refused with an error, the same way a negative capex is refused before the optimizer solves.", "The independent case: the correlation is clamped to 0.000000, so a hedge cannot be represented.", "The correlation as typed, so the funded projects'' spreads partly cancel and stdDev falls beneath independentStdDev.", "The magnitude of the correlation, since the driver weights take its square root and need a number that is not negative."]'::jsonb, 1, 'rho is clamped to run from 0 to 1: the published clampBelow case uses 0.000000 and reports stdDev 60.9438, the same as correlation_0.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 2, 'The published singleProject case runs at correlation 0.900000 and reports stdDev 46.8183. What would a different rho change in that stdDev?', '["It would shrink the stdDev as rho falls, since the shared driver''s weight sqrt(rho) scales the one project''s success spread.", "It would move the stdDev in step with rho, since a single project is correlated with the portfolio total it makes up alone.", "It would widen the stdDev toward the sum of the project''s success spread and its mixture sd as rho approaches 1.", "Nothing, because one project has no pair to correlate with, so the cross terms are empty at every rho."]'::jsonb, 3, 'stdDev is sqrt(sum var + rho x ((sum sd)^2 - sum var)); with one project (sum sd)^2 equals sum var, so rho multiplies zero.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 3, 'A team has measured how closely two plays'' successes and failures move together and types that measured figure into rho. What comes out?', '["A portfolio whose events move together less than observed, since the events a latent rho implies correlate lower than rho, so P(loss) and P90 come out too comfortable.", "A portfolio whose events move together more than observed, because the engine applies the one rho to both the success and the size drivers and so counts the dependence twice.", "The observed dependence exactly, because the success test normalCDF(z1) below pos passes the correlation of the drivers straight through to the events.", "A portfolio too pessimistic, because the correlation of yes or no events is always higher than the correlation of the drivers that produce them."]'::jsonb, 0, 'rho is the correlation of the hidden drivers z1 and z2; turning a driver into a yes or a no discards how far past the threshold it fell, so the measured event figure is the smaller number.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 4, 'Two projects carry the same pos. At which values of rho does the correlation between their success events equal rho itself?', '["At every rho when that pos is 0.500000, since a threshold at the middle of the curve cuts both drivers at the same point.", "At 0.500000 only, where the shared and own weights balance and the success test neither adds dependence nor removes it.", "At 0, where the events are independent, and at 1, where every z1 is F1 itself and successes come in a fixed nested order.", "At 1 only, since at 0 the thresholds still couple the events through the shared draws F1 and F2 that every project hears."]'::jsonb, 2, 'Between those ends the event correlation is lower than rho, and the engine does not report the event correlation a given rho implies.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 5, 'comonotoneIdentical3 has three wildcats at rho 1.000000, each pos 0.3, 300 on success and a fail cost of 50. Its exact P(loss) is 0.700000, the same as one wildcat. Why?', '["At rho 1 the three wells hear only F1 and fail together whenever one fails, so the portfolio loses exactly when a single well would.", "At rho 1 the three losses of 50.0000 are averaged rather than summed, so the portfolio is scored as one well carrying the average loss.", "At rho 1 the optimizer treats identical projects as duplicates and funds one well, so the risk summary is simulated for that one alone.", "At rho 1 the normal approximation becomes exact, and 0.700000 is the bell''s reading for three perfectly correlated wells."]'::jsonb, 0, 'Independent, the three fail together with chance 0.343000 and the copula case sits between at 0.469561; the low case is -150.0000 on all three rows, and only its frequency changes.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 6, 'A reviewer adds the four mixture sds of OKONO''s 600.0000 set, 44.3821 + 60.6850 + 121.9467 + 12.8750, and reports 239.8888 as the portfolio stdDev. What did the reviewer assume?', '["rho 0, since adding the standard deviations of independent risks is what an uncorrelated portfolio''s spread is built from in closed form.", "rho 1, since standard deviations add like money only under perfect correlation; at the optimizer default of rho 0 the figure is 143.8374.", "Nothing about rho, since the stdDev is always the sum of the sds and rho only reaches P(loss), P90 and P10 through the simulation.", "rho 0.600000, the point where the formula''s variance and cross terms carry equal weight and the sds sum without a square root."]'::jsonb, 1, 'At rho 1 the variances cancel inside the bracket and stdDev is sqrt(57546.6428) = 239.8888; at rho 0 the cross terms vanish and it is sqrt(20689.2080) = 143.8374.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 7, 'An analyst builds the spread formula for the 600.0000 set from success spreads, using OK-4''s 78.0305 in place of its mixture sd of 121.9467. What happens to stdDev?', '["It is overstated, because success spreads are read from npv_p10 and npv_p90, which bracket a wider range than the mixture variance does.", "It is unchanged at rho 1, where the formula reduces to the plain sum of the sds and it no longer matters which of its two sds each project contributes.", "It changes only for OK-5, the one project in the set with pos 1.000000, since its two spread columns are the only ones that differ.", "It is understated at every rho, because success spreads leave out the gap between a success centred on 210.0000 and a failure costing 40.0000."]'::jsonb, 3, 'The mixture sd is the square root of the success and failure variance taken together; only OK-5, with no fail cost, has the two columns agree, at 12.8750.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 8, 'On the 600.0000 set, raising rho from 0.000000 to 0.300000 lifts stdDev from 143.8374 to 178.1753, and the step of the same size from 0.600000 to 0.900000 lifts it only from 206.8905 to 232.0795. Why the smaller step?', '["The engine damps rho above 0.600000 so that the latent drivers stay standard normals, which trims the later steps of the rise.", "The cross terms shrink as rho rises, because each project''s own weight sqrt(1 - rho) falls and takes its share of the covariance with it.", "The stdDev is read from the simulated values, and the simulation saturates as the shared draw comes to dominate every project.", "The variance rises in a straight line with rho and stdDev is its square root, so equal steps in rho add less spread as rho grows."]'::jsonb, 3, 'At rho 0.300000 the engine adds 0.300000 times the gap between 57546.6428 and 20689.2080 to 20689.2080 and takes the root; the bracket is never negative, so rho can only widen the spread.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 9, 'At rho 0.600000 the risk summary prints stdDev 206.8905 beside P90 137.2208 for the 600.0000 set. A reader checks P90 as emv minus 1.2816 x stdDev and it does not match. Why?', '["P90 carries the sampling noise of seed 20260829, and the mismatch is about one standard error that a longer run at 40000 iterations would close.", "The multiplier 1.2816 holds only at rho 0, and at rho 0.600000 the engine derives P90 from a z adjusted for the correlation it was given.", "stdDev is the moment formula with rho on the project outcomes, while P90 comes from the simulation with rho on the latent drivers: two models that need not agree.", "P90 is the high case under the exceedance convention, so the check should add 1.2816 x stdDev to emv rather than subtract it from it."]'::jsonb, 2, 'The simulated P(loss), P90 and P10 are counted and sorted from outcomes; emv minus 1.2816 x stdDev was the normal approximation''s P90 and is history since EC5-0.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 10, 'In one iteration at rho 0.600000 the shared draw F1 comes out far above zero. What does that do to the funded projects?', '["It pushes every project''s z1 up at once, toward failure together, since a project succeeds when normalCDF(z1) is below pos.", "It pushes every project toward success at once, since a high shared draw stands for a favourable basin model that every project hears.", "It makes every success in that iteration larger than its npv_p50, since F1 is the shared driver that scales each success spread.", "It moves only the first project in array order, since F1 is consumed by the first project before the others draw their own normals."]'::jsonb, 0, 'F1 stands for what makes projects fail or succeed together, and F2 for what makes successes large or small together; z1 = sqrt(rho) F1 + sqrt(1 - rho) e1.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 11, 'A planner wants OK-1 and OK-4 to share a reservoir while OK-5 stands apart, and successes to correlate strongly while sizes correlate weakly. How does the engine take it?', '["By listing OK-5 last in array order, so its own normals are drawn after the shared ones and it hears less of F1 and F2.", "It cannot: one rho applies to every pair and to both the success and the size drivers, with no matrix and no cluster.", "By setting OK-5''s pos to 1.000000, which removes it from the shared success driver while leaving OK-1 and OK-4 tied.", "By running the risk summary twice at two correlations, once for success and once for size, and the engine combining the two runs."]'::jsonb, 1, 'z1 and z2 share the same sqrt(rho) weight, and every project hears the same F1 and F2; OK-5 still draws both normals in every iteration although its success is certain.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 12, 'The optimizer default leaves rho at 0 for OKONO''s 600.0000 set, OK-1 + OK-2 + OK-4 + OK-5. What does that choice claim?', '["That the four projects are correlated at the average the engine infers from their entered percentiles, so no choice has really been made by anyone.", "That the set is safe at any correlation, since the funded set was chosen at rho 0 and the optimizer would have dropped a correlated project.", "That infill drilling, gas compression, waterflood and workovers share no reservoir, price or operator, which is the most optimistic spread the engine can give.", "Nothing about dependence, since rho 0 is the engine''s code for a correlation that was not entered and is treated as missing."]'::jsonb, 2, 'At rho 0.000000 the set reads P(loss) 0.001800 and P90 200.3575; at rho 1.000000 it reads 0.059000 and 87.9316, so choosing rho is choosing the answer.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 13, 'At rho 1.000000 the 600.0000 set''s P(loss) climbs to 0.059000 and its P90 falls to 87.9316. What happens to emv and to the funded set?', '["emv stays 402.7500, but the optimizer drops OK-4 for a smaller project to narrow the spread the correlation has widened.", "emv falls toward P90, since the expected value of a correlated portfolio is discounted by the downside its projects share.", "emv rises with P10 to 674.8353, since a shared driver lifts the good iterations of every project together in the same draw.", "emv stays 402.7500 and the optimizer still funds OK-1 + OK-2 + OK-4 + OK-5, since rho reaches only the risk summary."]'::jsonb, 3, 'Each project keeps its risked EMV, OK-1 89.7500, OK-2 115.0000, OK-4 160.0000 and OK-5 38.0000, summing to 402.7500; the engine never trades a unit of EMV for a narrower spread.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 14, 'Why does emv read 402.7500 at every rho on the correlation table?', '["z1 = sqrt(rho) F1 + sqrt(1 - rho) e1 is still a standard normal, so each project succeeds with chance pos at any rho and only which projects succeed together changes.", "The weights sqrt(rho) and sqrt(1 - rho) add up to one at every rho, so the shared draw and the project''s own draw always average back to its npv_p50.", "The engine re-centres the simulated values on the closed-form emv at the end of every run, so the mean is held by the construction of the output.", "Correlation reaches only the failures, and emv is computed from the success-case NPVs alone, which the shared driver never touches at all."]'::jsonb, 0, 'The squared weights add to one, not the weights, and the average of a sum is the sum of the averages whatever the dependence. The emv printed is the closed form, with no simulated mean beside it.'),
  ('portfolio', 'advanced', 'module', 'm02-correlation', 15, 'As rho goes from 0.000000 to 1.000000, the 600.0000 set''s P10 rises from 580.5960 to 674.8353. A reader concludes correlation made the portfolio more valuable. What is the reply?', '["The reader is right that the high case gained, and the gain is offset exactly by the fall in P90, so the portfolio''s value is unchanged.", "The rise is the same widening seen from the other side: a shared driver brings good iterations together as surely as bad ones, and emv stays 402.7500.", "P10 is the low case under the exceedance convention, so its rise means the downside improved while the upside was left as it was.", "The rise is sampling noise, since P10 is read from the simulation at seed 20260829 and would fall back at another seed."]'::jsonb, 1, 'P90 falls from 200.3575 to 87.9316 over the same range; both tails move outward and the mean, the one figure correlation cannot touch, holds.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 1, 'On OFON-1, Ofon Energy''s working interest of 40.0000 percent gives a share of 10820000 USD. What is that figure?', '["Its share of the actuals to date, the amount the AFE bills Ofon Energy for the work invoiced so far.", "Its share of the EAC of 27600000, the partner''s forecast final exposure once every line is complete.", "Its share of the well''s value, the part of the project''s worth that the working interest entitles it to.", "Its share of the budget of 27050000, an authorisation, which is not what Ofon Energy owes today."]'::jsonb, 3, '27050000 x 40.0000 / 100 = 10820000. Split across the actuals to date of 15090000 the same interest bills 6036000; the interest does not change, only the total does.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 2, 'Can Ofon Energy be given a larger share of OFON-1''s completion line CMP-05 than of the drilling line DRL-01?', '["Yes, by entering a forecast on CMP-05 as CMT-03 carries one, since the split reads each line''s entered forecast before the total.", "No: the engine is handed one total and one list of interests, so the 40.0000 percent applies to every line and no line is split on its own.", "Yes, through the commitments column, since each line''s commitment is split by its own interest when orders are placed.", "Only after payout, when the engine switches from the cost interests to the revenue interests the partners agreed for that phase."]'::jsonb, 1, 'The split never looks at a forecast or a commitment. It has no carried interest, no non-consent and no change of interest before and after payout.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 3, 'Where does OFON-1''s operator share of 25.0000 percent come from?', '["It is typed in as the operator''s interest in the agreement, and the engine checks it against the partners'' total before splitting.", "It is the largest partner''s interest less the others, 40.0000 less 22.5000 and 12.5000 plus the operator''s own carried cost.", "It is computed as 100 less the partnerTotal of 75.0000, never typed in, so the four percents add to 100 by construction.", "It is a default the engine assigns to every operator, and partners are scaled to fill the remaining 75.0000 percent of cost."]'::jsonb, 2, 'Against the budget of 27050000 the residual is 6762500 and against the actuals to date of 15090000 it is 3772500. The operator absorbs every gap and every excess in the partner list.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 4, 'Suppose Mfem Resources, at 12.5000 percent, were never entered on OFON-1. What does the split report?', '["valid true with no note, and the operator''s residual silently absorbs Mfem''s 12.5000 percent of every bill.", "valid false with a note that the partner interests total less than the whole, so the shortfall is caught before billing.", "A refusal with an error, because the partner interests and the operator share must be typed to total 100 before any split.", "An operator share still at 25.0000, with 12.5000 percent of each bill left unallocated so the bills fall short of the cost."]'::jsonb, 0, 'valid true means only that the residual and every interest are not negative. The check is outside the engine: compare the operator''s residual with its own interest in the agreement, 25.0000 on OFON-1.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 5, 'The published 10 percent shortfall case splits 1000.00 with one partner at 10 percent, leaving the operator 90.0000 percent or 900.00, and returns valid true. What does valid true establish?', '["That the split matches the joint operating agreement, since the engine compares the residual with the operator''s recorded interest.", "That the partner list is complete, since a list summing to less than the whole would have been flagged with a note of its own.", "Only that no share is negative; it cannot tell an operator who really holds 90.0000 percent from a partner nobody entered.", "That the operator share is plausible, since the engine warns when the operator outweighs every partner."]'::jsonb, 2, 'There is no field for the operator''s own interest, so the engine has nothing to compare the residual against; the residual is arithmetic and the judgement belongs to the reader.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 6, 'On the published case at 70 and 45 percent, the amounts 700.00, 450.00 and -150.00 add back to the cost of 1000.00. A reconciler approves the bills because the sum matches. What was missed?', '["Nothing, because a split whose bills sum to the cost is balanced, and the negative operator amount is simply the operator''s credit for running the operation.", "The rounding, because two decimal places on each partner amount can hide a remainder that the sum check absorbs silently into the operator line.", "The commitments, because a sum check on the cost leaves out orders already placed, and each partner must also be billed its share of those.", "The split is valid false: the partners are billed for 115.00 percent of the work and the operator is shown receiving 150.00, so valid and the note must be read before any amount."]'::jsonb, 3, 'The operator share is 100 less 115.00, which is -15.0000 percent. The fix is in the partner list, since the operator share is computed and has no figure of its own to edit.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 7, 'How does the AFE engine treat a partner list totalling 115.00 percent, compared with a negative capex in the portfolio engine?', '["Both are refused with an error naming the bad entry, since neither input can produce a figure that is safe to show anyone.", "The partner list returns the full allocation with valid false and a note, while the negative capex is refused with an error and no result.", "The partner list is rescaled to 100 percent before the split and flagged, while the negative capex is clamped to 0 and funded.", "The operator share is clamped to 0.0000 and valid turns false, while the negative capex is read as a capex of 0 and weighs one cell."]'::jsonb, 1, 'Negative progress on a cost line is also refused. A flagged split keeps the numbers visible so the list can be traced, which puts the stop in the reader''s hands.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 8, 'The published negative interest case splits 1000.00 between partners at 30 and -20 percent. What does the engine return?', '["Partner amounts 300.00 and -200.00, an operator share of 90.0000 percent or 900.00, and valid false with a note naming Partner \"B\".", "The same allocation with valid true, because the total of 10 percent is under the whole and the operator share is not negative.", "A refusal with an error and no allocation, because a negative working interest is rejected before any amount is computed.", "The negative interest set to zero, an operator share of 70 percent, and valid false with a note that the interest was corrected."]'::jsonb, 0, 'The allocation is returned unchanged; the engine does not zero the interest, rescale the list or throw. Its note reads: Partner "B" has a negative working interest (-20.00 percent). Correct the interests before billing.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 9, 'On that case at 30 and -20 percent, what has the negative entry done to the operator?', '["Moved its magnitude onto the operator, who carries 90.0000 percent where it would carry 70 without the entry, while the partner bills itself a credit of 200.00.", "Nothing, since the operator share depends only on whether the partner total reaches 100, and a total of 10 percent leaves the operator at the same residual it would carry anyway.", "Reduced the operator''s load by 20 percent, since a partner''s negative interest is a contribution the operator deducts from its own share of cost.", "Split the credit between the operator and the positive partner, in proportion to their interests of 90.0000 and 30 percent of the cost."]'::jsonb, 0, 'Before EC5-0 this split passed as valid, because the only test was whether the operator share went below zero; a check that the total is at most 100 also passes it.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 10, 'The published case at 130 and -10 percent carries both errors. What does the note say, and in what order?', '["Only the sentence about the total of 120.00 percent, since a list over the whole takes precedence over any single entry.", "Both sentences, the total first, since the engine tests the partner total before it looks at any single partner''s entry.", "Both sentences, the negative interest first, then the partner total of 120.00 percent being more than the whole.", "Only the sentence about Partner \"B\", since the engine stops at the first error it finds."]'::jsonb, 2, 'The operator share is -20.0000 and the operator amount -200.00, valid false; the note names Partner "B" at -10.00 percent and then the total over the whole.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 11, 'A biller enters a partner at -20 percent to record a credit owed from an earlier phase. What does the split do with it?', '["It treats the negative interest as a carried interest, charging the operator for that phase and recovering the credit from the partner once the well reaches payout.", "It nets the credit against the partner''s next bill, since the split keeps a record of what each partner has already paid on the AFE.", "It converts the credit into a non-consent election, so the partner pays nothing toward the operation and the others take up its share.", "It models nothing of the kind: the operator share is inflated by the same magnitude, the partner''s bill pays the partner, and valid turns false."]'::jsonb, 3, 'The split has no field for a carry, a credit or a correction. Record the credit where credits belong and keep every working interest between 0 and 100.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 12, 'What does OFON-1 bill Ofon Energy, at 40.0000 percent, for the work to date?', '["10820000 USD, its share of the budget of 27050000 that the partners approved when the AFE was authorised.", "6036000 USD, 40.0000 percent of the actuals to date of 15090000.", "Its 40.0000 percent of the actuals plus the commitments of 5000000, since orders placed are costs the operator is already bound to.", "Its 40.0000 percent of the EAC of 27600000, since a partner is billed on the forecast that every screen shares after EC5-0."]'::jsonb, 1, 'Partners are billed on actuals, not the budget or the EAC. The four bills, 6036000 + 3395250 + 1886250 + 3772500, sum to 15090000.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 13, 'Applied to OFON-1''s EAC of 27600000, what does a partner''s working interest give?', '["The amount to bill once the as-of date passes the end of the window, when the forecast becomes the actual cost of the well.", "The cash call for the next month, since the split issues advance billing against the forecast before any invoice arrives.", "The partner''s share of the variance at completion, billed when a line overruns.", "A forecast of that partner''s final exposure, useful for its own planning and wrong on an invoice."]'::jsonb, 3, 'The EAC is a forecast and the budget of 27050000 an authorisation; the split has no cash call and no advance billing against a forecast.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 14, 'OFON-1 records actuals of 15090000 on its cost lines and an invoice total of 15090000. What should a partner bill say about that?', '["Which total it split, because the two agree by construction on OFON-1 and need not agree on a real AFE.", "Nothing, because the engine reconciles invoices with cost lines and refuses a split that disagrees.", "That it split the larger of the two, since the rule every screen shares after EC5-0 takes the larger of any two recorded actuals.", "That it split the invoices, since the cost lines hold commitments and not money spent."]'::jsonb, 0, 'The metrics read actuals from the cost lines and the S-curve reads them from invoices. The split applies one set of interests to whatever total it is handed and converts nothing.'),
  ('portfolio', 'advanced', 'module', 'm03-joint-venture-shares', 15, 'Before EC5-0, what did the AFE summary PDF bill for an AFE whose saved partners were Ofon Energy, Enang Petroleum and Mfem Resources?', '["The three saved partners on the budget of 27050000, because the PDF read the approved total rather than the actuals.", "The three saved partners with the operator left out, so the operator''s 25.0000 percent was missing from the printed split.", "Two invented partners, Partner A at 30 percent and Partner B at 10 percent, whatever partners had been saved.", "The three saved partners with no note, so an invalid split printed without its warning."]'::jsonb, 2, 'The repaired PDF bills the AFE''s saved partners and prints the engine note whenever the split is invalid; a screen that hides valid and the note bills an error quietly.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 1, 'The published negativeCapexUnnamed case refuses with PortfolioInputError: "Project "1" has a negative capex (-0.5); capex must be 0 or more". The project carries no name. Which project in the list is it?', '["The first project, because the engine numbers the rows of the inventory from 1, the way a reader counts the rows of the Suite table.", "Whichever project carries an id of 1, because the message falls back to the id field when the name field is missing.", "The second project, because an unnamed project is named by its position in the list counted from 0.", "No project in particular, since \"1\" counts the refusals raised so far and this case holds a single negative capex."]'::jsonb, 2, 'The unnamed refusal counts from 0, so "1" is the second entry, and its size does not matter: -0.5 is refused as firmly as -150.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 2, 'When negativeCapexRefused fires on project "B" with a capex of -150, what does the optimizer return?', '["No set, no frontier and no risk summary: the PortfolioInputError and its message are the whole result.", "The best set among the other projects, with B left out of the inventory and the message attached to the result as a warning.", "The best set with B clamped to a capex of 0, the treatment a pos of 1.4 or a negative fail_cost receives without any warning.", "The best set with overLimit true, since funding B would add 150 to the limit and the flag marks a limit that stopped meaning a limit."]'::jsonb, 0, 'A refusal stops the engine and a flag returns an answer; a negative capex is refused, while a pos of 1.4 is clamped and quietly returns 80.0000.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 3, 'A user gets past the negative capex refusal by typing 0 in place of -150. Why is that not a safe repair?', '["A capex of 0 gives the project a risked EMV of 0, since the risked EMV is scaled by capex, and a project with EMV of 0 or less is never funded.", "The engine refuses a capex of exactly 0 as well, because the message is read as capex must be more than 0, so the edit trades one refusal for another.", "The optimizer ranks projects by EMV per million USD before it fills the limit, so a capex of 0 raises a division by zero inside the ranking.", "A free project is still charged one grid cell (finding D2), and whatever the negative number carried, such as a receipt, belonged in the NPV and has vanished."]'::jsonb, 3, 'In freeProjectTightLimit a free project with EMV 10.0000 beside A at capex 100.0000 under a limit of 100.0000 is dropped: the engine funds A alone for 60.0000 where the exact optimum is 70.0000.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 4, 'Three copies of a project with npv_p50 80 and fail_cost 30 leave pos out, type it as "n/a", and type it as an empty string. What risked EMVs come back?', '["80.0000 for the first and a PortfolioInputError for the other two, because a typed pos that is not a number is refused like a negative capex.", "80.0000, 80.0000 and -30.0000: an absent or non-numeric pos defaults to 1, while an empty string is the number 0 and reads as certain failure.", "80.0000 three times, because every pos the engine cannot read as a number falls back to the documented default of 1.", "-30.0000 three times, because a pos that is missing or unreadable is treated as a chance of success of 0 until one is typed in."]'::jsonb, 1, 'None of the three is refused or flagged; the blank pos read as -30.0000 is finding EC5-6, left unrepaired and taught as a property of the engine.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 5, 'Project T is entered with capex "abc" beside project U at capex 40, under a limit of 100. What does the optimizer return?', '["A PortfolioInputError naming T, because the capex check refuses any value that is not a number of 0 or more before the grid is built.", "T + U at a total capex of 40.0000, because \"abc\" counts as capex 0, weighs one grid cell and is neither refused nor flagged.", "U alone at 40.0000, because a capex the engine cannot read as a number drops that project from the inventory before the grid is built.", "T + U with overLimit true, because a capex that is not a number is flagged the same way the grid overshoot is flagged."]'::jsonb, 1, 'The probe funds T + U at capex 40.0000 and EMV 80.0000; a non-numeric capex is finding EC5-7, a property of the engine as published, and only reading the inventory catches it.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 6, 'An AFE line described as "Completion" is entered at -0.5 percent progress. What does the engine return?', '["The metrics with that line clamped to 0 percent, since a fraction of a percent below zero is read as a line that has not yet begun.", "The metrics with valid false and the message printed as a note, the way the joint venture split reports a negative working interest.", "The metrics with that line left out of earned value and out of the budget, so CPI and SPI are computed on the remaining lines.", "An AfeInputError, \"Cost item \"Completion\" has negative progress (-0.5 percent). Progress runs from 0 to 100 percent.\", and no metrics at all."]'::jsonb, 3, 'The size does not matter, -0.5 is refused as firmly as -20; clamping to 0 would hide a typing error as a line not yet begun.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 7, 'The negative progress message says progress runs from 0 to 100 percent. A published case enters progress beyond 100 percent. What does the engine do with it?', '["It accepts it and earns beyond the budget: earned value 150.0000 against actuals of 90.0000, a CPI of 1.666667 and an SPI of 1.500000.", "It refuses it with the same AfeInputError, because the message states both bounds and the check enforces the range it prints.", "It clamps the line to 100 percent, so earned value stops at the budget and the CPI cannot pass the budget over the actuals.", "It returns the metrics with a flag on the line, the way the grid overshoot returns its set beside overLimit true."]'::jsonb, 0, 'Only the lower bound is enforced; a CPI of 1.666667 reads as a line far ahead on cost when it has earned more than its budget can hold, a finding left unrepaired.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 8, 'An AFE with no dates is asked for its metrics as of 30 February and refuses with "asOf is not a valid date". What would a valid as-of date have moved on that AFE?', '["Planned value and SPI, because the engine builds a window that ends on the as-of date whenever the AFE carries no dates of its own.", "Earned value and CPI, because each line''s progress is prorated to the as-of date before it is multiplied by the line''s budget.", "Nothing, because with no dates time progress falls back to 1.000000, so the date is refused as an input whatever the arithmetic does with it.", "The EAC, because the forecast rule switches every line from its entered forecast to the formula once the as-of date passes the last day of the AFE window."]'::jsonb, 2, 'A lenient parser would roll 30 February into March and report on a day nobody chose; the published no-dates case returns time progress 1.000000 and SPI 0.250000.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 9, 'gridOvershoot now returns A + B at capex 6002.0000 and EMV 800.0000, with overLimit true and overLimitBy 2.0000. What did the EC5-0 repair change about that answer?', '["The set: the engine now re-solves on the exact capex and reports A + C at 780.0000, keeping overLimitBy 2.0000 to record the overshoot it avoided.", "The limit: the engine now widens it to 6002.0000 so that the set is feasible, and overLimitBy records how far the limit had to move.", "The capex: the engine funds B at 2.0000 less than its cost so the set fits, and overLimit true warns that B is funded short.", "Only the marking: the same set comes back and now says it breaks the limit, and the engine never re-solves to A + C at 780.0000."]'::jsonb, 3, 'The overshoot is flagged and still happens; ranking 800.0000 against a feasible 780.0000 prefers the set the budget cannot pay for, a golden gap of 20.0000.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 10, 'In gridOvershoot the limit of 6000.0000 runs on a resolution of 3.000000. Why does A + B, at a real capex of 6002.0000, fit the grid?', '["Rounding capex over 3.000000 weighs A at 1333 cells and B at 667, which fill the 2000 cells exactly.", "The limit and every capex are whole numbers, so the grid runs at 1 million USD per cell and the 2.0000 excess stays inside one cell.", "The engine admits any set within one cell of the limit, and an excess of 2.0000 is smaller than the resolution of 3.000000.", "B and C round to the same number of cells, so the grid cannot tell them apart and keeps whichever of the two was entered first."]'::jsonb, 0, 'Above a limit of 5000 each cell is the limit / 2000; rounding drops a fraction of a cell from A and from B, which is why the flag reports overLimitBy 2.0000.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 11, 'gridUndershoot funds X + Y + Z at capex 4500.0000 and EMV 660.0000 under a limit of 6000.0000, and reports overLimit false. What does that false establish?', '["That the set is the best within the limit, since the repaired engine re-solves on the exact capex and compares the two answers before it sets the flag.", "That rounding changed nothing, since overLimit is raised whenever the grid and the exact capex disagree in either direction.", "Only that the funded capex is within the limit: the exact optimum funds all four at 860.0000, a gap of -200.0000 that no flag reports (finding D4).", "That 1500.0000 was left unspent by choice, because W at 1499.0000 carries the lowest EMV of the four and was not worth its capex."]'::jsonb, 2, 'Rounding makes the four together weigh more cells than the 2000 the grid holds, so one is left out; the undershoot is unflagged and taught as a property.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 12, 'A joint venture split on a cost of 1000.00 enters partner interests of 30 and -20. Is that a refusal or a flag, and what comes back?', '["A refusal: an AfeInputError naming partner \"B\" and no allocation at all, the same treatment the AFE engine gives a cost line entered with negative progress or a bad as-of date.", "A flag: valid false with the engine note naming partner \"B\" and its -20.00 percent, and the allocation still shown with the operator at 90.0000 percent.", "A flag, with the -20 interest clamped to 0, so partner \"B\" is billed nothing and the operator is shown carrying 70.0000 percent.", "Neither: the split nets the two interests to 10 percent, so the operator carries 90.0000 percent and valid stays true."]'::jsonb, 1, 'Partner amounts read 300.00 and -200.00 and the operator 900.00; the repaired AFE summary prints the note beside the allocation instead of billing on it.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 13, 'EC5-0 made SPI null where planned value is zero, yet the published empty AFE, with no lines and no spend, reports SPI 1.000000. Why?', '["The empty AFE has no dates, so time progress falls back to 1 and planned value becomes the whole budget, which is no longer zero.", "SPI copies CPI whenever actuals are 0, and CPI on the empty AFE reads 1.000000 because nothing at all has been spent on it.", "The null rule applies only up to the start day, and an AFE with no lines is treated as already past the end of its window.", "An AFE whose budget is 0 reports SPI 1 by a guard that fires before the null rule, a finding left unrepaired."]'::jsonb, 3, 'The same empty AFE also reports CPI 1.000000, so an AFE with no lines, no progress and no spend reads as perfect on cost and on schedule at once.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 14, 'OFON-1''s S-curve starts at "Feb 27" in UTC, Lagos and Tokyo, but a viewer in America/Los_Angeles sees the first point labelled "Jan 27" and every Planned value shifted. What is going on?', '["The engine parses the window as UTC midnight but steps months and prints labels in local time, finding EC5-5, left unrepaired.", "The as-of date west of UTC is still the previous day, so that viewer''s curve is drawn for a different as-of date than the metrics.", "The saved window is converted to the viewer''s time zone when it is stored, so that viewer has edited the AFE window into January.", "The repaired curve opens a month before the window to show commitments, and only viewers west of UTC are shown that month."]'::jsonb, 0, 'OFON-1''s window opens 2027-02-01, and in UTC its first point is Feb 27 with Planned 0; west of UTC the same AFE carries other labels and other plan values with no warning.'),
  ('portfolio', 'advanced', 'module', 'm04-refusals-and-flags', 15, 'In the Suite the correlation slider stops at 0.9, where OKONO''s 600.0000 set reads stdDev 232.0795 and P(loss) 0.049500. How should that top value be read?', '["As the engine''s clamp: any correlation above 0.9 is cut back to 0.9, which is what the published clampAbove case exists to show.", "As the largest correlation the simulation can hold, because a correlation of 1 makes sqrt(1 - rho) zero and the draws collapse.", "As the app''s limit, never the engine''s: the engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000, which the screen cannot set.", "As a harmless cap, because the emv of 402.7500 does not move with correlation, so the last step of the slider would change nothing that is reported."]'::jsonb, 2, 'The published clampAbove case reads correlation used 1.000000; the slider stopping at 0.9 is an app item left as published, so the most correlated case has to be run on the engine and named.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 1, 'OFON-1 with every actual set to 0 and progress unchanged reports earned value 15231500 and CPI 1.000000. What does that CPI say about cost performance?', '["That the work done cost exactly what it earned, since earned value is compared with the 5000000 committed when no actual has posted.", "Nothing: earned value over zero actuals has no value, and the engine returns 1 whenever actuals are 0, the number an AFE exactly on budget shows.", "That the AFE is on budget to the unit, because with nothing spent no line can yet have overrun its share of the 27050000 budget.", "That CPI is capped at 1 until the first invoice posts, so the 1.009377 the lines earned is held back until the costs catch up with the progress."]'::jsonb, 1, 'OFON-1 as entered reads 1.009377 on actuals of 15090000; with actuals at 0 the 15231500 earned is either costs not yet posted or progress typed ahead of the work, and CPI hides both.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 2, 'With every OFON-1 actual set to 0, which of its numbers as of 2027-08-15 still reads what it read before?', '["EAC 27600000, because a line with no entered forecast forecasts its budget, and setting the actuals to 0 leaves every budget unchanged.", "CPI 1.009377, because CPI is read from progress and budget alone, and the actuals only feed the variance at completion.", "Percent spent 55.7856, because percent spent is measured against commitments, and the commitments are untouched when actuals are zeroed.", "SPI 0.872063, because earned value 15231500 never uses actuals and planned value 17466060 comes from the calendar."]'::jsonb, 3, 'The forecast rule takes the larger of the budget and actual plus commitment, so CSG-02, which forecast its actual of 4300000, moves with the actuals and the EAC moves with it.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 3, 'The published "past window, all invoices unpaid: none dated" case holds an invoice of 100 with no invoice_date field and one of 200 whose invoice_date is null. Its first and last Actual both read 200. Why?', '["The null date counts from 1970, earlier than every bucket, so the 200 sits in all 12 points, while the invoice with no date field never counts.", "The invoice of 200 has no date field and is placed at the first bucket, while the null-dated invoice of 100 is discarded as unpaid.", "The curve falls back to the cost lines when no invoice carries a usable date, and the case''s single line of budget 1200 shows 200 spent.", "Both invoices are placed at the window start, and the 100 is netted against the 200 as a credit because neither can be put in date order."]'::jsonb, 0, 'At Jan 20 Planned is still 0 while Actual reads 200, and at Dec 20 it shows 200 beside Planned 1101: a total that matches neither what was invoiced nor when.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 4, 'OFON-1''s invoice of 5200000 is dated 2027-04-10. At which S-curve point does it first appear, and why?', '["Apr 27, because a label names the month an invoice falls in, and every invoice dated inside that month is summed into its point.", "Jun 27, because an invoice is booked one whole month after its date to allow for payment, which is the lag behind every step.", "May 27, where Actual steps from 3100000 to 8300000, because each point counts only invoices dated on or before its own day, the 1st of the month.", "Aug 27, because the S-curve reads actuals from the cost lines, and only the as-of date of 2027-08-15 brings them onto the curve."]'::jsonb, 2, 'Point 0 at Feb 27 reads 0 because nothing is dated before the window opens; a curve reading above 0 at its first point has counted something dated before its window, and a null date is the first suspect.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 5, 'OFON-1''s last Actual on the S-curve, 15090000, equals the actuals on its cost lines. What makes the two agree?', '["The engine derives each line''s actual from the dated invoices, so the metrics and the curve share one source of spend by construction.", "The teaching field was built so: the metrics read the cost lines, the S-curve reads the invoices, and nothing in the engine reconciles them.", "The engine refuses an AFE whose invoice total differs from its line actuals, in the same way it refuses a line with negative progress.", "The as-of date of 2027-08-15 falls after the last invoice, and from that date on the curve switches its Actual line to the cost lines."]'::jsonb, 1, 'A null-dated invoice pushes the curve ahead of the lines and a missing date leaves it behind, while the CPI of 1.009377 is computed from line actuals the curve never uses.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 6, 'OFON-1''s window runs 2027-02-01 to 2027-11-30 on a budget of 27050000, and the S-curve''s last Planned point is 24452483. Why does the plan end 2597517 short?', '["The plan spreads the budget less the 5000000 already committed, since commitments are drawn on the Actual line and cannot be planned twice.", "The plan holds back a contingency that is released only when the AFE closes, and the metrics carry that contingency inside the EAC instead.", "EC5-0 cut the curve at the as-of date of 2027-08-15 and extended the plan past it from the monthly rate, which loses the last weeks.", "Each point sits on the 1st of its month, so the last one is the 1st of November and the rest of the window to 2027-11-30 is never plotted."]'::jsonb, 3, 'The metrics do reach the budget: as of 2027-11-30 time progress is 1.000000 and planned value 27050000, so the chart and the metrics disagree about the same plan.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 7, 'A reader of OFON-1''s S-curve alone sees the last Forecast point at 24949669, below the budget of 27050000. What does the AFE actually forecast?', '["An overrun: an EAC of 27600000 and a variance at completion of -550000, cut short on the chart by the same last bucket that stops the plan.", "A saving, since the Forecast line is the only projection that reads the invoices, while the metrics forecast every unposted line at its full budget.", "Exactly the budget, because a line with no entered forecast forecasts its budget and the chart has simply not reached the last day yet.", "Both at once, an underrun on the chart and an overrun in the metrics, since the curve forecasts only to the as-of date and the metrics to completion."]'::jsonb, 0, 'After the as-of date the Forecast line is the EAC spread from the start and stops at the last bucket; take the EAC and the variance from the metrics and use the curve for its shape.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 8, 'The published "future window ending on a bucket" case has 13 points, and its last point reads Planned 2000 and Forecast 2450, the whole EAC. What decides whether a curve''s last point reaches the budget?', '["The size of the budget, since each monthly bucket of plan is rounded to whole units of the AFE currency, and a budget as small as 2000 loses nothing to that rounding.", "Whether any invoices exist, since a curve with no invoices has no Actual line to cut off and so draws its plan to the end of the window.", "Where the end date falls against the month starts: a window ending on the 1st gets a point there, and OFON-1, ending on 2027-11-30, loses almost a month.", "The as-of date, since a default as-of date after the window lets the plan run to completion while a dated report stops the plan."]'::jsonb, 2, 'The one-year 2020 case has 12 points and ends at Planned 1101 on Dec 20 against a budget of 1200, and OFON-1''s last Planned point is 24452483 against 27050000.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 9, 'On OKONO''s 450.0000 set at the default seed, P(loss) reads 0.123600 at 10000 iterations and 0.125975 at 40000. What did quadrupling the iterations buy?', '["A standard error cut to a quarter of its 10000 iteration value, since the error of a counted probability shrinks in step with the number of draws.", "A result free of the seed, since at 40000 draws every seed converges on the same P(loss) to the fourth decimal and the seed stops mattering.", "A move toward the exact answer of 0.142035, which is the value the simulation converges on for this set as the draws grow.", "A standard error that fell from 0.003291 to 0.001659, roughly half, and nothing about whether the model of the projects is right."]'::jsonb, 3, 'The standard error is sqrt(p(1 - p) / n), so four times the draws halves it: 0.010050 at 1000 iterations, 0.003291 at 10000 and 0.001659 at 40000.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 10, 'At 10000 iterations OKONO''s 450.0000 set reads P(loss) 0.128500 at seed 1, 0.127700 at seed 2 and 0.119100 at seed 3. Is that range wider than sampling alone explains?', '["Yes: seed 3 draws a stream biased toward success, which is why the engine publishes 20260829 as its calibrated default seed.", "No: each run''s standard error lies between 0.003239 and 0.003346, and seeds a few standard errors apart are what sampling alone produces.", "Yes: at 10000 iterations every seed should agree to the fourth decimal, so a spread in the second decimal points to a fault in the random draws themselves.", "No: the three runs differ only in rounding, since a seed changes the order of the draws and never the count of losses among them."]'::jsonb, 1, 'A seed buys a reproducible number and iterations buy a smaller standard error; neither buys a correct model, and rerunning seeds until P(loss) looks acceptable only picks sampling noise.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 11, 'OKONO''s 450.0000 set reads a Low case P90 of -15.1262 at 1000 iterations, -18.3574 at 10000 and -18.8524 at 40000, and -21.8586 to -15.3254 across seeds 1 to 3. What belongs to the set?', '["That the Low case P90 is below zero, which every run agrees on; its fourth decimal moves with the sample, and the engine prints no standard error for it.", "The value -18.3574 to four decimals, because a percentile is read straight off the sorted draws rather than averaged from them, and so carries no sampling error of its own.", "The value -57.1494, because the closed-form formula emv - 1.2816 x stdDev uses no draws at all and so removes the sampling noise that moves every simulated run.", "The average of the six runs, because averaging over seeds and iteration counts removes the sampling noise carried by each run."]'::jsonb, 0, 'The Low case P90 is the 10th percentile of simulated portfolio NPV and wobbles by several million USD between runs; -57.1494 is the normal approximation, a different model.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 12, 'The published riskMethod cases carry an exact answer, a standard error and a z. The single wildcat reads 0.696100 against an exact 0.700000, a z of 0.8510, and no case sits further than 1.4289. What does a seeded simulation promise?', '["Agreement with the true loss probability of the projects within 1.4289 standard errors, whatever inventory is entered.", "A loss probability that never exceeds the exact answer, since the z is measured on one side of the exact value only.", "Agreement with its own model''s exact answer within sampling error, and nothing more than that about the projects.", "Agreement with the normal approximation within sampling error, since both methods rest on the same moments of the projects."]'::jsonb, 2, 'The normal approximation gave the wildcat 0.365832, a different model with a different answer; the simulation''s own model still funds whole projects under one average correlation with a normal success spread.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 13, 'OKONO''s 600.0000 set reports P(loss) 0.001800 at the optimizer''s default correlation of 0. What can a reader conclude about how safe the set is?', '["That it is safe, because correlation widens the spread but leaves the emv of 402.7500 alone, and a portfolio can only lose money when that mean itself falls below zero.", "That it is safe only under a correlation of 0: the same set reads 0.059000 at rho 1.000000, and one average rho gives every pair of projects the same link.", "That it is safe to within its standard error, since P(loss) is counted from 10000 draws on a published seed that anyone can rerun, and a reproducible number is a trustworthy one.", "That it is unsafe, since a P(loss) as small as 0.001800 is below what 10000 draws can resolve, so the engine has returned the mark of a failed simulation run."]'::jsonb, 1, 'stdDev widens from 143.8374 to 239.8888 as rho goes from 0 to 1; two projects that share a facility look like two that share nothing, and the model cannot test which is true.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 14, 'A reviewer says the exploration well''s lopsided entries, a high case far further from its middle value than its low case, are honoured by every simulated draw. What does the model actually do with them?', '["As two half-normal spreads, one fitted above 420.0000 and one below it, so the upward lean of the entered values is kept in every draw.", "As a lognormal fitted through all three entered values, the shape the engine gives any project that carries a success spread.", "As the entered values themselves, drawing an outcome between 210.0000 and 700.0000 with an equal chance anywhere in that range.", "As one symmetric normal spread of 191.1747, (700.0000 - 210.0000) / 2.5631, which discards the upward lean of the entered values."]'::jsonb, 3, 'A normal success spread is a property of the model that no run changes: 700.0000 sits further above 420.0000 than 210.0000 sits below it, and the spread of 191.1747 treats both sides alike.'),
  ('portfolio', 'advanced', 'module', 'm05-numbers-to-distrust', 15, 'OFON-1 earns 15231500 because DRL-01 is typed at 72.0000 percent and CMT-03 at 55.0000 percent. What does its CPI of 1.009377 measure?', '["Spending against physical work the engine verifies, since each line''s progress is cross-checked against its invoices on the S-curve.", "Spending against the calendar, since earned value is the budget times the share of the window elapsed at the as-of date.", "Spending against progress someone typed: the engine checks no progress entry, so the CPI inherits whatever those percentages claim.", "Spending against the budget alone, since CPI is the budget over the actuals and the progress entries only feed SPI."]'::jsonb, 2, 'DRL-01 earns 14200000 at 72.0000 percent, 10224000 of the 15231500; the SPI of 0.872063 inherits the same entries, which is why the assumption is named beside the number.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Before EC5-0 the risk summary gave the single wildcat (pos 0.300000, npv_p50 300.0000, fail_cost 50.0000) a Low case P90 of -150.5560. What was wrong with it?', '["It was too optimistic, since the exact low case of a lone wildcat lies further below zero than -150.5560 once the fail cost is risked.", "It was right but imprecise, since a normal approximation settles on the exact low case once enough projects are added to the portfolio.", "It lay below the worst possible outcome of -50.0000, a low case no portfolio could reach; the simulation''s P90 is -50.0000, an outcome that can happen.", "It was right for the model and wrong for the inventory, since the wildcat''s fail_cost of 50.0000 had been entered as a loss in every year."]'::jsonb, 2, 'The same approximation put P(loss) at 0.365832 against an exact 0.700000; the engine now draws success and failure and reads 0.696100 at seed 20260829 and 10000 iterations.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 2, 'A reviewer raises the correlation on OKONO''s 600.0000 set from 0 to 1 and expects its risked value to fall. What moves?', '["The spread and the loss probability: stdDev widens from 143.8374 to 239.8888 and P(loss) climbs from 0.001800 to 0.059000, while emv stays 402.7500.", "The emv, which falls as projects that fail together drag the expected value down, while stdDev is fixed by the entered spreads.", "The funded set, since the optimizer re-solves under the new correlation and swaps projects to diversify the portfolio.", "Only the P10, because correlation stretches the upper tail alone on a portfolio whose projects all carry a positive emv."]'::jsonb, 0, 'One average correlation widens the spread and never moves the mean; the optimizer maximises summed risked EMV and correlation plays no part in choosing the set.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A capstone split returns valid false with an engine note. What does the expert answer do with the allocation?', '["Bills the partners on the allocation shown and attaches the note, since the engine still returns an amount for every party in the split.", "Scales the interests so that they total 100 percent and bills on the scaled shares, which is the correction the note asks for.", "Bills the operator its share and holds only the partners'' bills, since only a partner interest can make the split invalid.", "Quotes the engine note and bills nobody until the interests are corrected, even though the allocation is still shown."]'::jsonb, 3, 'In the published case with interests of 70 and 45 the operator share is -15.0000, an amount of -150.00 on a cost of 1000.00, so billing on the allocation bills a negative operator.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The capstone order starts with the inputs. Why write one risked EMV by hand, such as OK-3''s, before running anything?', '["The engine reports only the summed EMV of the funded set, so a project''s own risked EMV exists nowhere unless it is worked out by hand.", "A clamp or a default changes an input silently, so 0.250000 x 420.0000 - 0.750000 x 85.0000 = 41.2500 confirms the engine read what was typed.", "OK-3''s success-case NPV of 420.0000 is its value, and the hand calculation shows how much of that value the grid keeps after rounding.", "The hand figure is the one the capstone grades, since the engine rounds each project''s risked EMV to a whole million USD."]'::jsonb, 1, 'A pos of 1.4 or "n/a" returns 80.0000 on the published case with no warning; OK-3''s risked EMV of 41.2500 is only 0.098214 of its success-case NPV.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 5, 'OKONO at 450.0000 funds OK-1 + OK-3 + OK-4 at resolution 1.0000 with overLimit false. On a run whose resolution is coarser than 1 million USD per cell, what must the answer add?', '["Nothing further, because overLimit false on a coarse grid certifies both that the set is feasible and that no better set was missed.", "The exact optimum, which the repaired engine reports beside the grid answer whenever the resolution is coarser than 1 million USD.", "Whether overLimit fired, and that an undershoot (D4) or a free project charged a cell (D2) would not be flagged.", "A rerun on a different seed, since a coarse grid is sampled rather than solved and the funded set moves from one seed to the next."]'::jsonb, 2, 'gridUndershoot shows why: overLimit false and EMV 660.0000, where the exact optimum is 860.0000.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 6, 'OKONO''s 450.0000 set reads P(loss) 0.123600 and a Low case P90 of -18.3574. What must be written beside them?', '["The seed 20260829, the 10000 iterations, and the correlation used, stated as one average number.", "The resolution and overLimit of the set, since the simulated numbers are only as good as the grid that chose the set.", "The standard error alone, since a seed changes only the order of the draws and cannot move the count of losses.", "The exact answer and its z, since the engine prints both beside every loss probability it simulates for a funded set."]'::jsonb, 0, 'Without its seed the same set could read 0.119100 or 0.128500, and at 1000 iterations its standard error is 0.010050.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 7, 'OFON-1 reads SPI 1.141290 as of 2027-06-30 and 0.872063 as of 2027-08-15 on the same lines. Which of its numbers move with the as-of date?', '["Planned value, SPI and CPI, since the actuals are counted up to the as-of date the same way the S-curve counts dated invoices.", "Earned value and SPI, since progress is prorated to the as-of date before it is weighted by the budget.", "SPI and the EAC, since the forecast rule switches a line to actual plus commitment once the as-of date passes its spend.", "Planned value and SPI; earned value 15231500, CPI 1.009377 and the EAC of 27600000 are read from the lines as entered."]'::jsonb, 3, 'Planned value is 13345861 at 2027-06-30 and 17466060 at 2027-08-15, so SPI moves while every number built on the lines alone does not; each SPI is right only for its date.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 8, 'OFON-1''s EAC is 27600000 by one forecast rule. Which lines forecast something other than their budget?', '["DRL-01 and LOG-04, whose actual plus commitment of 12400000 and 1250000 sit below budget and so replace the budget as their forecast.", "CSG-02, at its actual plus commitment of 4300000, and CMT-03, at its entered 1400000.", "CSG-02 alone, because an entered forecast above the budget is ignored and CMT-03 falls back to its budget of 1250000.", "Every line with spend posted, forecast at its actual plus commitment."]'::jsonb, 1, 'The rule takes a positive entered forecast, otherwise the larger of the budget and actual plus commitment; the variance of -550000 is -400000 on CSG-02 and -150000 on CMT-03.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A capstone answer quotes OFON-1''s CPI of 1.009377, correctly, with nothing beside it. Why does it lose marks?', '["A CPI needs its as-of date beside it, because CPI moves with the date in the same way SPI moved from 1.141290 to 0.872063.", "A CPI needs its seed beside it, because every ratio in an expert capstone is simulated and moves from one run to the next.", "A CPI needs the actuals total beside it, 15090000 here, because 1.000000 is also what the engine reports when actuals are 0.", "A CPI above 1 has to be reported as 1, because the engine caps each performance ratio at the budget before it writes the report."]'::jsonb, 2, 'A correct number with its condition missing loses marks: a P90 without a seed, an SPI without an as-of date, a set without overLimit, and a CPI without the actuals total.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 10, 'An answer reports OFON-1''s EAC as 24949669, read off the last Forecast point of the S-curve. What has it done?', '["Turned an overrun into an apparent saving: the EAC is 27600000 with a variance of -550000, and the curve''s last bucket cuts the Forecast line short.", "Reported the EAC correctly as of 2027-08-15, since the curve''s Forecast line is the only projection that takes the as-of date into account.", "Reported the forecast before commitments, which the metrics add on top of the curve''s last value to arrive at the EAC.", "Reported the plan instead of the forecast, since the two lines trade places after the as-of date and that point belongs to Planned."]'::jsonb, 0, 'The last Planned point is 24452483 and the last Forecast point 24949669, both below the budget of 27050000; take the EAC from the metrics and use the curve for its shape.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 11, 'OKONO at 600.0000 is rerun on a different seed. Which of its results can change?', '["P(loss) and the stdDev of 143.8374, which is the spread of the simulated draws and moves with them.", "P(loss) and the funded set as well, because the optimizer breaks ties between sets of equal EMV by a draw on the seed.", "None of them, because a seed fixes only the order of the draws, and every order of the same draws yields the same count of losses.", "P(loss), the Low case P90 and the P10, which are simulated; the set, emv 402.7500 and stdDev 143.8374 are not."]'::jsonb, 3, 'emv and stdDev are closed form and the optimizer keeps the first best set it builds; at 450.0000, P(loss) runs from 0.119100 to 0.128500 across seeds 1 to 3.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Which question do the portfolio and AFE engines hand over to field development planning?', '["Which whole projects to fund under a limit, since the portfolio engine only ranks the projects by EMV per million USD and leaves the set to be chosen by hand.", "When a project''s capex is spent and when first production arrives, since the portfolio engine takes each NPV as typed and never phases capex.", "How widely a funded set''s value could fall, since the risk summary is a screening estimate that planning replaces with its own.", "How each partner is billed for money spent, since the AFE engine tracks the budget and leaves working interests to planning."]'::jsonb, 1, 'Neither engine shapes a development, chooses a well count or says whether a project should exist; OKONO at 450.0000 is a defensible set only on the NPVs entered.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which sentence reports the P(loss) of OKONO''s 450.0000 set the way this tier asks?', '["P(loss) is 0.123600 at seed 20260829 and 10000 iterations, with a standard error of 0.003291, under a correlation of 0.", "P(loss) is 0.123600 on the default settings, with the standard error of 0.010050 that any probability counted from the draws carries.", "P(loss) is 0.142035, what this set''s emv and stdDev give once the noise of any one seed is taken out.", "P(loss) is 0.123600 to six decimals, a figure the seed makes exact, so that no standard error needs to be printed beside it."]'::jsonb, 0, '0.010050 is the standard error at 1000 iterations, not at 10000; 0.142035 is what the normal approximation would have said, a different model.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Working the set, an answer places OKONO''s 450.0000 optimum beside the ranking by EMV per million USD. What does the comparison show?', '["The two agree at 291.0000, since OK-3 ranks last by EMV per million USD and the ranking reaches it once the cheaper projects are funded.", "The ranking wins at 291.0000 and the optimizer trails at 287.7500, because the grid charges OK-3 an extra cell that pushes it out.", "The ranking funds OK-3 first for its success-case NPV of 420.0000; the optimizer drops it for OK-5.", "The ranking funds OK-1 + OK-4 + OK-5 at 287.7500, while the optimizer funds OK-1 + OK-3 + OK-4 at 291.0000."]'::jsonb, 3, 'The ranking spends 420.0000 of the 450.0000; the best set is not the best projects, and OK-3 is funded at 450.0000 and dropped again at 600.0000.'),
  ('portfolio', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Checking OFON-1''s inputs before the AFE is read, an answer finds every progress at 0 or more. What must it still point out?', '["Nothing more, because the engine refuses progress outside 0 to 100 percent, exactly as its message says, so a report that returns metrics has passed both bounds of the check.", "Any line at 0 percent, because the engine treats a line not yet begun as refused progress and drops its budget from planned value.", "Any progress above 100 percent, which the engine accepts and which earns value beyond the budget, as the published case''s CPI of 1.666667 shows.", "Any line at 100 percent, such as CSG-02, because a complete line is clamped and its actual of 4300000 is taken out of CPI."]'::jsonb, 2, 'Negative progress throws AfeInputError, but only the lower bound is enforced; CSG-02 sits at 100.0000 percent with actuals of 4300000 against a budget of 3900000 and could be pushed past 100 with no refusal.'),
  ('portfolio', 'advanced', 'final', null, 1, 'A committee pack from before EC5-0 quotes -150.5560 as the P90 of a single exploration well that succeeds three times in ten, earns 300 on success and costs 50 on failure. What was wrong with that figure?', '["It was too optimistic, because a well failing 0.700000 of the time has a true low case further down than -150.5560.", "It lies beneath -50.0000, the worst outcome the well can produce, so it describes a loss no draw of this project can ever reach.", "Nothing of substance, because a low case below the worst outcome only adds a margin a committee reads as conservative.", "It carried the wrong label, because under the exceedance convention the low case of that well is its P10."]'::jsonb, 1, 'A risked project is success or a single failure point, and the bell smoothed that gap away; the simulation now returns P90 -50.0000, the failure itself.'),
  ('portfolio', 'advanced', 'final', null, 2, 'Across identical wildcats the old approximation understated P(loss) with three wells (0.276275 against an exact 0.343000) and overstated it with six (0.200464 against 0.117649). Why can no fixed margin repair the old figures?', '["The error shrinks steadily as wells are added, so a margin fitted on one well overcorrects every larger portfolio it is applied to.", "Only the P90 error changes sign between three and six wells, so a margin would repair the probabilities and leave the low cases wrong.", "The approximation turns exact once six wells are funded, so only smaller portfolios need a margin.", "The error changes sign as wells are added, so nothing tells a reviewer which way to lean on a given portfolio."]'::jsonb, 3, 'With eight wells it understated again, 0.166046 against 0.255298, so the direction of the error follows the lumps and not a trend.'),
  ('portfolio', 'advanced', 'final', null, 3, 'In one simulated iteration OKONO''s OK-3 (pos 0.250000, npv_p50 420.0000, fail cost 85.0000) fails. What does the risk simulation book for it?', '["A loss of exactly 85.0000 with no spread, since its success spread of 191.1747 scales z2 only when the project succeeds.", "Its npv_p90 of 210.0000, the low percentile of its entered range, booked as the downside of a poor outcome.", "A loss drawn around 85.0000 on its mixture sd of 238.6507, so a single failure can cost a little more or a little less than entered.", "Its risked EMV of 41.2500, because the simulation books each project''s expected value in every iteration."]'::jsonb, 0, 'A failure is one number, booked in about three iterations out of four; the mixture sd feeds only the closed-form stdDev and is never drawn.'),
  ('portfolio', 'advanced', 'final', null, 4, 'An analyst reruns OKONO''s 450.0000 set, the same OK-1, OK-3 and OK-4, at seed 20260829 and 10000 iterations, but enters them as OK-4, OK-3, OK-1. P(loss) no longer reads 0.123600. What happened?', '["Project order decides which project hears the shared drivers F1 and F2, so the reordered set was simulated under a different correlation.", "Entering OK-4 first made its fail cost the threshold for every draw, so losses were counted from another zero.", "The normals were dealt to the projects in a different order, so the same set at the same seed moved by sampling noise alone.", "A seeded run is meant to ignore how the list is typed, so a result that moves with the input order is a defect the repair left in place."]'::jsonb, 2, 'Each iteration draws F1, F2, then e1 and e2 per project in array order, so reproducing 0.123600 needs the seed, the iterations and the project order.'),
  ('portfolio', 'advanced', 'final', null, 5, 'A risk review calls two portfolios equally dangerous because both lose money about as often: identical6 at an exact 0.117649, OKONO''s funded 450.0000 set at a simulated 0.123600. What does the pairing show?', '["That the two portfolios hold about the same downside, because an equal loss probability places their low cases at the same percentile of simulated NPV.", "P(loss) says how often and never how much: every identical6 loss is -300.0000, while the 450.0000 set reads a P90 of only -18.3574.", "That identical6 is the safer, because its losses need all six wells to fail and a joint failure costs less than a partial one.", "Nothing usable, because a binary portfolio''s loss probability cannot be set beside one with a success spread."]'::jsonb, 1, 'identical6 loses only when all six wells fail, so its loss is the floor itself; a loss probability has to be read beside the low case.'),
  ('portfolio', 'advanced', 'final', null, 6, 'identical8''s engine P90 is -50.0000. A reviewer writes it up as the worst this eight-well portfolio can do. What is the correction?', '["The label is swapped: -50.0000 is the high case P10 under the exceedance convention, so the low case is elsewhere.", "The sample is too small: 10000 iterations cannot reach an outcome beyond the exact P90, so the worst case of eight wells is unknown to the engine.", "None is needed, because on a lumpy portfolio the engine reports the minimum simulated outcome as its P90.", "P90 is the 10th percentile of simulated NPV, here one success and seven failures, and all eight wells failing loses more."]'::jsonb, 3, 'The engine reports no minimum, so the worst outcome, every well failing at 50.0000, is written by hand beside the P90.'),
  ('portfolio', 'advanced', 'final', null, 7, 'On mixtureWithSpread the normal approximation put P90 at -12.4175 and the simulation reads 1.7148. What would a reader of the old figure have concluded wrongly?', '["That the low case loses money, when nine outcomes in ten are at or above a small gain.", "That -12.4175 was the very worst the portfolio could do, when the simulation shows its worst outcome is a gain of 1.7148.", "That the portfolio was lumpy, when a success spread makes the outcomes continuous and the old approximation exact on such a case.", "That the high case was a gain, when the committee should have read P10 first because it is the low case under exceedance."]'::jsonb, 0, 'The exact P90 outcome is 1.5838, so the sign of the low case changed with the model; the approximation was exact only on the pos1-normal cases.'),
  ('portfolio', 'advanced', 'final', null, 8, 'At rho 0.000000 OKONO''s 600.0000 set prints emv 402.7500 and stdDev 143.8374. A reviewer derives its low case as emv - 1.2816 x stdDev. Why does that disagree with the reported P90 of 200.3575?', '["The multiplier belongs to P10, so the low case needs emv plus 1.2816 x stdDev, and the reviewer has quoted the high tail.", "The repaired engine derives P90 from the closed-form stdDev only when rho is above 0, and at rho 0 it switches to a separate formula.", "That shortcut is the normal approximation EC5-0 retired, 218.4079 here, while the reported P90 is counted from simulated draws of success and failure.", "It does not disagree in substance, because at rho 0 the closed form and the simulation are the same model and the gap is sampling noise."]'::jsonb, 2, 'At 300.0000 the same shortcut gives 108.3959 against a simulated 100.7698; a bell on a risked set misses the low case in either direction.'),
  ('portfolio', 'advanced', 'final', null, 9, 'An analyst has a historical figure for how often two prospects in one basin succeed and fail in step, and enters that event correlation directly as rho. How does the risk summary come out?', '["Too alarming a P(loss) and P90, because rho acts on outcomes and a measured correlation of successes already includes the size of each success.", "Too comfortable a P(loss) and P90, because rho correlates the latent drivers and the event correlation it produces is lower.", "The same figures as the right input, because the engine converts an event correlation into a driver correlation.", "A lower emv, because a correlation typed from observed outcomes pulls each project''s chance of success down."]'::jsonb, 1, 'Between 0 and 1 the event correlation is less than rho, so the measured figure understates the drivers; at rho 1 three identical wildcats fail together, exact P(loss) 0.700000.'),
  ('portfolio', 'advanced', 'final', null, 10, 'A team enters a negative correlation to represent two projects that hedge each other. What does the portfolio engine do with it?', '["Refuses it with a PortfolioInputError and returns no risk summary, exactly as it refuses a negative capex before any set is built.", "Returns the full risk summary marked invalid with an engine note, the way a negative working interest returns valid false.", "Takes its magnitude, because the sign of a correlation only decides which tail the shared driver pushes and the spread is the same.", "Clamps it to 0.000000 and simulates the projects as independent, so no hedge can be represented."]'::jsonb, 3, 'The published clampBelow case uses correlation 0.000000 and stdDev 60.9438, the rho 0 figure; a correlation is clamped, where a capex is refused and a share is flagged.'),
  ('portfolio', 'advanced', 'final', null, 11, 'A reviewer checks the stdDev of OKONO''s 600.0000 set at rho 1 by adding the four projects'' success spreads. Why does the check fall short of 239.8888?', '["The formula uses mixture sds, which carry the gap between success and failure; OK-4 alone is 121.9467 against a success spread of 78.0305.", "Adding standard deviations is the rho 0 end of the formula, and at rho 1 the engine adds the variances and takes the square root instead.", "The engine applies rho to the latent drivers, so its stdDev at rho 1 always runs above the plain sum of whichever sds are added.", "The closed form counts each cross term twice over, so its figure at rho 1 exceeds any plain sum of the four spreads by construction."]'::jsonb, 0, 'At rho 1 stdDev is sqrt(57546.6428) = 239.8888, exactly 44.3821 + 60.6850 + 121.9467 + 12.8750 added like money.'),
  ('portfolio', 'advanced', 'final', null, 12, 'identical3, copulaIdentical3 and comonotoneIdentical3 hold the same three wells. Exact P(loss) runs 0.343000, 0.469561 and 0.700000, yet the exact P90 outcome is -150.0000 on every row. Why?', '["The low case of a binary portfolio is set by the fail costs alone and never reads pos, so correlation cannot move it on any portfolio.", "Correlation moves the spread and never the mean, and on a portfolio of binary wells the low case is part of what the mean fixes.", "All three failing together is at least 0.343000 likely on every row, more than one draw in ten, so the 10th percentile already sits on that floor.", "The copula and comonotone rows were published with the P90 column copied from the independent row, since the exact percentile was not solved."]'::jsonb, 2, 'On OKONO''s 600.0000 set no lump is that likely, and its P90 falls from 200.3575 to 87.9316 as rho rises from 0 to 1.'),
  ('portfolio', 'advanced', 'final', null, 13, 'A committee leaves rho at its default for OK-1, OK-2, OK-4 and OK-5 and reports P(loss) 0.001800. What has it asserted about the projects?', '["Nothing about them, since the default is neutral and the engine replaces it with the correlation implied by the inventory''s own spreads.", "That the four share no reservoir, no price and no operator, the most optimistic dependence the engine accepts.", "That they hedge one another, which is why the default gives the lowest loss probability.", "Only that the sizes of their successes are independent, since rho acts on the success spread and leaves the chance of success to pos."]'::jsonb, 1, 'rho 0 is independence and the floor of the clamp; the same set reads P(loss) 0.059000 at rho 1.000000, so choosing rho is choosing the answer.'),
  ('portfolio', 'advanced', 'final', null, 14, 'A committee raises rho to 1.000000 at the 600.0000 limit, watches P90 drop to 87.9316 and P(loss) reach 0.059000, and expects the engine to swap in a safer set. What does the optimizer fund?', '["OK-1 + OK-3 + OK-4 + OK-5, trading risked EMV for a set that the shared driver ties together less tightly than the waterflood and compression.", "A set with fewer large projects, because once correlation is above the default the optimizer charges each project''s stdDev against its EMV.", "OK-1 + OK-3 + OK-4, the 450.0000 optimum, because the frontier is rebuilt at each correlation and its sets are not nested across budgets.", "OK-1 + OK-2 + OK-4 + OK-5, as at every rho, because rho reaches only the risk summary."]'::jsonb, 3, 'The optimizer maximises summed risked EMV, which is 402.7500 at every rho; a committee that wants a narrower low case compares sets by hand.'),
  ('portfolio', 'advanced', 'final', null, 15, 'Between rho 0.000000 and 1.000000 the 600.0000 set''s P10 rises from 580.5960 to 674.8353. How should that rise be read?', '["As the same widening seen from the high tail: a shared driver brings good iterations together as surely as bad ones.", "As an upside to bank, since P10 is the low case under exceedance and its rise cuts the downside.", "As a gain in value offsetting the fall in P90, so that the expected outcome of the set stays level only by coincidence at this budget.", "As sampling noise, since correlation only pushes the low tail and a moving high tail is the seed."]'::jsonb, 0, 'P90 falls from 200.3575 to 87.9316 over the same range while emv holds at 402.7500, the one figure correlation cannot touch.'),
  ('portfolio', 'advanced', 'final', null, 16, 'In the Suite an analyst wants OKONO''s 600.0000 set at full dependence and drags the correlation slider to its top. What does the screen show?', '["The rho 1.000000 figures, because EC5-0 extended the slider to the engine''s full range when it replaced the normal approximation.", "An engine refusal, because the engine clamps correlation at 0.9 and throws for any value above it.", "The rho 0.900000 figures, stdDev 232.0795 and P(loss) 0.049500, because the slider stops at 0.9, an app item left unrepaired.", "The rho 1.000000 figures under a flag, since the slider''s top is labelled 0.9 but passes the clamped maximum of 1 through to the engine."]'::jsonb, 2, 'The engine accepts 1 and reads stdDev 239.8888 and P(loss) 0.059000 there; read the slider''s top as the app''s limit, never the engine''s.'),
  ('portfolio', 'advanced', 'final', null, 17, 'An analyst sends Ofon Energy, at 40.0000 percent of OFON-1, a bill of 10820000 today. What is wrong with it?', '["Nothing, because a working interest is a share of the approved cost and the budget of 27050000 is exactly the cost the partners approved.", "10820000 is the share of the budget, an authorisation; on the actuals to date of 15090000 the same interest bills 6036000.", "The party is wrong: 10820000 is the operator''s residual, and Ofon Energy owes 6762500 today.", "It should be split on the EAC of 27600000, since a partner is billed its share of the forecast final cost once the AFE is approved."]'::jsonb, 1, 'The interest does not change between the two totals, only the total does, and the four bills on actuals sum to 15090000.'),
  ('portfolio', 'advanced', 'final', null, 18, 'Ofon Energy asks for its share of OFON-1''s final exposure, for its own planning. Which total should its 40.0000 percent be applied to?', '["The budget of 27050000, because every line with no entered forecast forecasts its budget and the final exposure therefore equals the budget share.", "The actuals plus the commitments of 5000000, because orders already placed become the partner''s final exposure once they are invoiced.", "The actuals of 15090000, because a working interest applies only to money spent and a forecast of the remainder is the operator''s concern.", "The EAC of 27600000, a forecast by one rule, used for planning and never put on an invoice."]'::jsonb, 3, 'CSG-02 forecasts its actual of 4300000 and CMT-03 its entered 1400000, which is why the variance at completion is -550000; bills split the actuals to date.'),
  ('portfolio', 'advanced', 'final', null, 19, 'The OFON-1 partner list is keyed in with Ofon Energy and Enang Petroleum only, and Mfem Resources with its 12.5000 percent is left off by mistake. What does the split return?', '["valid true with no note, while the operator''s residual silently absorbs Mfem''s 12.5000 percent of every bill.", "valid false with a note that the interests fall short of the whole, because a shortfall is flagged in the same way as a total over it.", "A refusal naming the missing partner, checked against the joint operating agreement.", "valid true with the operator held at 25.0000 percent and the missing 12.5000 percent left unbilled until someone enters the partner."]'::jsonb, 0, 'The published 10 percent shortfall reads valid true with the operator at 90.0000; there is no field for the operator''s own interest, so the check is by hand.'),
  ('portfolio', 'advanced', 'final', null, 20, 'On the published split at 70 and 45 percent of a cost of 1000.00, the two partner amounts and the operator''s add back to 1000.00. What does that reconciliation prove?', '["That the allocation can be billed, because amounts that sum to the cost are how the engine defines valid.", "That the engine rescaled the interests to the whole before allocating, so the amounts come back to the cost.", "Nothing about the split, since the operator''s -150.00 restores the sum; valid false and the partner total of 115.00 percent catch it.", "That only the operator''s figure needs editing to 0 percent, after which the partners'' 700.00 and 450.00 can be billed as they stand."]'::jsonb, 2, 'The note says the interests total 115.00 percent and the operator share is negative; the fix is in the partner list, never in the computed operator figure.'),
  ('portfolio', 'advanced', 'final', null, 21, 'Partner interests of 30 and -20 percent on a cost of 1000.00 leave the operator 90.0000 percent. Why did this split pass as valid before EC5-0?', '["The engine zeroed the negative interest first, so the split it tested was 30 percent with the operator at 70.", "The only test was whether the operator share went below zero, and a partner total of 10 percent leaves the residual positive.", "valid was computed from the amounts, and a partner credit of -200.00 plus the operator''s 900.00 and the 300.00 still sum to the cost.", "A negative interest was read as a carry, which the split models as a credit owed from an earlier phase."]'::jsonb, 1, 'Since EC5-0 it returns valid false naming Partner B at -20.00 percent; the negative entry moved 20 points onto an operator that would otherwise carry 70.'),
  ('portfolio', 'advanced', 'final', null, 22, 'The AFE split flags a negative working interest, while the portfolio engine refuses a negative capex. What separates the two behaviours?', '["Nothing in effect, because a flagged split also withholds every amount until the interests are corrected and the split is run again.", "The flag clamps the negative interest to 0 and allocates the rest, while the refusal throws only because a capex has no safe clamp.", "The refusal fires on large errors such as -150 and the flag on small ones, so a capex of -0.5 would also be allocated with a warning.", "The refusal returns no set, frontier or risk summary; the flag returns the whole allocation with valid false and a note, so the error can be traced."]'::jsonb, 3, '-0.5 is refused as firmly as -150, while interests of 30 and -20 still show the operator at 900.00 beside the engine note.'),
  ('portfolio', 'advanced', 'final', null, 23, 'OFON-1''s line actuals and its S-curve''s last Actual point both read 15090000, and a biller splits whichever is to hand. When would the S-curve total bill partners on the wrong amount?', '["When an invoice has a null date, which counts from 1970 in every bucket, or has no date field and never counts at all.", "When a line carries an entered forecast, which the curve''s Actual line then follows.", "When commitments are open, since the curve adds orders placed to each Actual point while the cost lines hold commitments apart.", "Never, because the engine reconciles invoices to the line actuals before drawing the curve and refuses an AFE on which they differ."]'::jsonb, 0, 'In the published undated case a null-dated 200 puts Actual 200 on the first point and the dateless 100 never appears; a bill should name which actuals it split.'),
  ('portfolio', 'advanced', 'final', null, 24, 'A project with npv_p50 80 and fail_cost 30 is typed with pos 1.4. What does the portfolio engine do?', '["Refuses it with a PortfolioInputError naming the project, the same treatment it gives a negative capex before building a set.", "Uses 1.4 as typed, so the risked EMV exceeds the success-case NPV and the project ranks above every certain project in the inventory.", "Reads pos as 1 and returns risked EMV 80.0000, with nothing on the result to say the input changed.", "Marks the project invalid and funds it anyway, the way the grid returns an overshooting set beside overLimit true."]'::jsonb, 2, 'posAboveOneClamps returns 80.0000 and posBelowZeroClamps returns -30.0000; clamps are caught only by reading the inventory.'),
  ('portfolio', 'advanced', 'final', null, 25, 'To get past the message that Project B has a negative capex (-150), an analyst types 0 in its place. What has the analyst made?', '["A clean entry the optimizer funds at no cost under any limit, since a capex of 0 weighs nothing on a grid of 1 million USD per cell.", "A free project that the grid still charges one cell (D2), with whatever the negative number carried gone from the model.", "A second refusal, since a capex of 0 is below the smallest grid cell and throws another error.", "The same project with its receipt kept, because a refused capex is booked into the NPV first."]'::jsonb, 1, 'In freeProjectTightLimit a free project with EMV 10.0000 is dropped beside A at 100.0000, so the engine returns 60.0000 where the exact optimum is 70.0000.'),
  ('portfolio', 'advanced', 'final', null, 26, 'A published AFE case with progress beyond 100 percent returns earned value 150.0000, actuals 90.0000 and CPI 1.666667. How should that CPI be read?', '["As strong cost performance, because the engine refuses progress outside 0 to 100 percent and the input must therefore be valid.", "As a clamped figure, because progress above 100 is read as 100 and the earned value of 150.0000 includes the line''s commitment.", "As SPI printed in the cost column, since progress past the whole moves only SPI.", "With suspicion, since only negative progress is refused and the line has earned more than its budget can hold."]'::jsonb, 3, 'The refusal message says progress runs from 0 to 100 percent, yet the upper bound is not enforced; the same case reads SPI 1.500000.'),
  ('portfolio', 'advanced', 'final', null, 27, 'An as-of date of 30 February is refused on an AFE that has no window, where time progress falls back to 1.000000 and the date would move nothing. Why refuse it?', '["A lenient parser would roll it into March and report on a day nobody chose, so every invalid as-of date is refused first.", "Because an AFE with no window reads SPI from the as-of date alone, so a bad date would misplace the plan.", "Because 30 February is read as the start day, where SPI is null, and a report with no SPI is declined.", "Because an invalid date would set time progress to 1 on an AFE with no window, and the engine blocks that fallback."]'::jsonb, 0, 'The published case throws "asOf is not a valid date" with no AFE dates; negative progress throws the same way, returning no metrics at all.'),
  ('portfolio', 'advanced', 'final', null, 28, 'gridOvershoot returns A + B at 800.0000 with overLimit true and overLimitBy 2.0000 against a limit of 6000.0000. What belongs in the committee''s comparison?', '["A + B at 800.0000, since 2.0000 over the limit is inside one grid cell of 3.000000 and the engine counts that as within the limit.", "A + B with 2.0000 of capex trimmed, since overLimitBy tells the committee exactly how much to cut to make the higher EMV feasible.", "A + C at 780.0000, found by hand, since the flag marks A + B infeasible and never re-solves.", "A alone at 500.0000, since a flagged set is discarded and the engine falls back to the largest single project that fits the limit."]'::jsonb, 2, 'The golden gap is 20.0000; ranking 800.0000 against 780.0000 prefers the set the budget cannot pay for.'),
  ('portfolio', 'advanced', 'final', null, 29, 'gridUndershoot funds X + Y + Z at 660.0000 with overLimit false. What does overLimit false tell the reader?', '["That the grid found the best set within the limit, since the flag reports any case rounding changed.", "That the resolution of 3.000000 was fine enough, since a grid that misses a better set also flags.", "That W was rightly dropped, since its EMV of 200.0000 is the lowest and a full grid drops the lowest.", "Only that the set fits the limit; the exact optimum funds all four at 860.0000, and the undershoot (D4) is never flagged."]'::jsonb, 3, 'Rounding makes the four weigh 500, 500, 500 and 501 cells against a grid of 2000, so a gap of -200.0000 passes with no flag.'),
  ('portfolio', 'advanced', 'final', null, 30, 'Which of these is a finding EC5-0 left in place, taught as a property of the engines as published?', '["SPI reported as Infinity before the start date when value had already been earned.", "CPI reported as 1.000000 whenever actuals are 0.", "A normal approximation whose P90 sits beneath the worst outcome of a single wildcat.", "An S-curve that keeps walking past its end date to the current month."]'::jsonb, 1, 'OFON-1 with every actual at 0 still earns 15231500 and reports CPI 1.000000, while SPI is now null before and on the start day and the curve stops at 10 points.'),
  ('portfolio', 'advanced', 'final', null, 31, 'Suppose OFON-1''s cost postings are wiped so every line shows zero spend while progress stays as typed, and CPI now prints 1.000000. As of 2027-08-15, which reading keeps both its value and its meaning?', '["SPI 0.872063, because earned value ignores actuals and planned value comes from the calendar.", "The EAC of 27600000, because the forecast rule reads budgets and entered forecasts and never looks at the actuals on a line.", "The variance at completion of -550000, because a zero actual moves only the S-curve''s Actual line and none of the metrics.", "CPI itself, because 1.000000 records that the work done matched the money spent to the unit, which is still true with nothing spent."]'::jsonb, 0, 'SPI is 15231500 over 17466060; CSG-02 forecast from its actual of 4300000, so zeroing the actuals does move the EAC.'),
  ('portfolio', 'advanced', 'final', null, 32, 'The published empty AFE reports CPI 1.000000 and SPI 1.000000. What should a report say about those two figures?', '["That the AFE is exactly on cost and exactly on schedule, since both ratios equal one and neither depends on the date.", "That SPI should read null, since the repair made SPI null wherever planned value is zero and the published 1.000000 is a stale golden.", "That CPI means something here and SPI does not, since 0.0000 over 0.0000 is defined as one.", "Both are placeholders: CPI is 1 when actuals are 0, and SPI is 1 on a zero budget by a guard that fires before the null rule."]'::jsonb, 3, 'An AFE with no lines, no progress and no spend reads as perfect on cost and schedule at once; SPI 1 on a zero budget is a finding left unrepaired.'),
  ('portfolio', 'advanced', 'final', null, 33, 'An S-curve''s first point reads Planned 0 and Actual 200. What is the first suspect?', '["An invoice with no invoice_date field, which the engine places on the start day of the window because it has no other date to read.", "Spending genuinely ahead of plan, because Actual reads the cost lines and a line posted in the first month shows at the first point.", "An invoice with a null date, which is counted from 1970 and so sits in every bucket.", "A commitment counted as spend, because the curve''s Actual line adds the orders placed at the start of the window to its first point."]'::jsonb, 2, 'In the published undated case the null-dated 200 reads from Jan 20 to Dec 20 and the dateless 100 never appears; a dated invoice first shows at the point after its date.'),
  ('portfolio', 'advanced', 'final', null, 34, 'As of 2027-11-30 OFON-1''s metrics report planned value 27050000, but the S-curve''s last Planned point is 24452483. Which should a report quote as the plan?', '["The curve, because the 2597517 it never plots is contingency the plan never meant to spend.", "The metrics: time progress is 1.000000 on the end day, while the curve''s last point sits on the first of November.", "The curve, because the metrics read the plan from the budget while the curve builds it from invoices, which are the better record.", "Neither, because SPI is null on the end day and planned value is undefined once the window has closed."]'::jsonb, 1, 'The plan stops 2597517 short because the monthly buckets end before the window does; use the curve for its shape and the metrics for the number.'),
  ('portfolio', 'advanced', 'final', null, 35, 'A project manager glances at OFON-1''s chart, sees the final projected point of 24949669 sitting under the 27050000 authorisation, and tells the partners the well will come in cheap. What is the correction?', '["After the as-of date the Forecast line continues from the actual spend of 15090000, so 24949669 is the honest projection of the remaining work.", "The curve plots only budgets after the as-of date, so CMT-03''s 1400000 is missing.", "EC5-0 put one EAC rule on every screen except the chart, so the curve still forecasts from the budget and the manager''s reading stands.", "The last bucket stops before the end date; the metrics forecast 27600000, a variance at completion of -550000."]'::jsonb, 3, 'After the as-of date Forecast is the EAC spread from the start, which is why it jumps from 15090000 to 19374834; take the EAC and variance from the metrics.'),
  ('portfolio', 'advanced', 'final', null, 36, 'OKONO''s 450.0000 set reads P(loss) 0.123600 at seed 20260829 with a standard error of 0.003291, where the old approximation said 0.142035. A reviewer proposes 40000 iterations to settle which is right. What will the run settle?', '["Only the simulation''s own precision, 0.125975 with a standard error of 0.001659; the gap to 0.142035 is a different model, which no iteration count closes.", "Which model is right, because as iterations grow the simulated count converges on the normal approximation and the gap closes.", "Nothing at all, because the larger run reuses the default seed and so repeats the draws of the 10000 iteration run exactly.", "That the approximation was nearer the truth, since 0.125975 sits closer to 0.142035 than 0.123600 did and the trend runs toward it."]'::jsonb, 0, 'The published cases sit no further than 1.4289 standard errors from exact, while the old approximation missed the single wildcat''s 0.700000 by dozens.'),
  ('portfolio', 'advanced', 'final', null, 37, 'A team that wants the 450.0000 set to look safer tries seeds until it finds 0.119100 at seed 3, having also seen 0.128500 at seed 1, all at 10000 iterations, and reports only the seed 3 figure. What is wrong?', '["Nothing, because seed 3''s result is exactly reproducible and reproducibility is what EC5-0 added to the risk summary.", "Seed 3 is right for another reason: its standard error of 0.003239 is the smallest of the seeds.", "It picked the draw that flatters the set; the seeds differ by what sampling alone produces, and the set''s risk is unchanged.", "The team should average the seeds, since their mean is the true loss probability of the set."]'::jsonb, 2, 'Standard errors between 0.003239 and 0.003346 make that spread ordinary noise; an honest report names the seed and iterations beside the figure.'),
  ('portfolio', 'advanced', 'final', null, 38, 'At a limit of 750.0000 OKONO funds five projects for 690.0000 and leaves 60.0000 unspent. A manager asks why the engine did not fund part of OK-6 with it. What is the answer?', '["OK-6''s risked EMV per million USD of 0.464516 falls below the cut-off the optimizer applies to leftover money at the end of a solve.", "Projects are funded whole; OK-6 costs 310.0000, and a farm-down or phased start does not exist for the engine.", "A fraction of OK-6 would not fill one whole cell of the grid at 750.0000.", "The risk summary rejects a set whose P(loss) rises, and a share of OK-6 would lift the set''s 0.012800 above what the engine allows."]'::jsonb, 1, 'The resolution is 1.0000 at that limit; at 1000.0000 the whole of OK-6 fits and the set reaches 588.0000.'),
  ('portfolio', 'advanced', 'final', null, 39, 'OK-3''s entered success range runs from 210.0000 at its low percentile to 700.0000 at its high one, with a median of 420.0000, so more room sits above the centre than below. What survives into the simulated successes?', '["Both tails, drawing successes above 420.0000 on a wider spread than the successes it draws below that centre.", "The mixture sd of 238.6507 as the spread of a success, because that is the figure that folds the lopsided range into one number.", "The npv_p90 of 210.0000 as a floor, so that no simulated success of OK-3 can fall below its entered low percentile.", "Only its width, one symmetric success spread of 191.1747, and the upward skew is discarded."]'::jsonb, 3, '(700.0000 - 210.0000) / 2.5631 = 191.1747; a normal spread is symmetric, and a wide one can even put a success below zero.'),
  ('portfolio', 'advanced', 'final', null, 40, 'Each of these capstone lines quotes a correct number. Which one loses marks?', '["OFON-1: SPI 0.872063.", "OKONO at 450.0000: P(loss) 0.123600 at seed 20260829, 10000 iterations, correlation 0.", "OFON-1: CPI 1.009377 beside actuals of 15090000.", "OKONO at 450.0000: OK-1 + OK-3 + OK-4, capex 450.0000, EMV 291.0000, resolution 1.0000, overLimit false."]'::jsonb, 0, 'SPI moves with the date, 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15 on the same lines, so an SPI without its as-of date is incomplete.'),
  ('portfolio', 'advanced', 'final', null, 41, 'Working OKONO at 600.0000, which reported figure would change if the risk summary were run on a different seed?', '["The emv of 402.7500, the risked value summed across the four funded projects.", "The stdDev of 143.8374 given by the closed-form spread formula at rho 0.", "The P90 of 200.3575, which is read from the simulated draws.", "The funded set OK-1 + OK-2 + OK-4 + OK-5 chosen by the optimizer."]'::jsonb, 2, 'emv and stdDev are closed forms and the optimizer never reads the draws; P(loss) 0.001800 and P10 580.5960 move with the seed as well.'),
  ('portfolio', 'advanced', 'final', null, 42, 'An inventory submitted to the Capital Portfolio Studio contains a project whose capex is -150. What P90 does the risk summary report?', '["The P90 of the set with that project clamped to capex 0, as odd inputs are clamped.", "None, because the PortfolioInputError throws first and the engine returns no set, no frontier and no risk summary.", "A P90 carrying a flag, since the repaired engine returns the answer and marks the negative capex the way it marks an overshoot.", "The P90 of the set without that project, since a refused project is simply dropped."]'::jsonb, 1, 'The message names the project, "capex must be 0 or more", and a simulated low case exists only for a set the engine agreed to build.');
